#include "unity.h"
#include "app.h"
#include "mock_bsp_led.h"    /* generated by CMock from Bsp/Inc/bsp_led.h */
#include "mock_bsp_time.h"

void setUp(void)
{
    bsp_time_now_ms_ExpectAndReturn(0u);
    bsp_led_set_Expect(BSP_LED_GREEN, false);
    app_init();
}

void tearDown(void) {}

void test_step_before_interval_leaves_led_alone(void)
{
    bsp_time_now_ms_ExpectAndReturn(499u);
    app_step();            /* any bsp_led_set() call here fails the test */
}

void test_step_at_interval_turns_led_on(void)
{
    bsp_time_now_ms_ExpectAndReturn(500u);
    bsp_led_set_Expect(BSP_LED_GREEN, true);
    app_step();
}

void test_second_interval_turns_led_off(void)
{
    bsp_time_now_ms_ExpectAndReturn(500u);
    bsp_led_set_Expect(BSP_LED_GREEN, true);
    app_step();

    bsp_time_now_ms_ExpectAndReturn(1000u);
    bsp_led_set_Expect(BSP_LED_GREEN, false);
    app_step();
}